Rules.InvariantScript:
UpdateContext(
    {
        var_visibleFormEmergencia: true,
        var_acaoFormEmergencia: "Cadastrar emergência",
        var_dadosEmergencia: Blank()
    }
);
NewForm(FormCadastrarEmergencia)

UpdateContext(
    {
        var_visibleFormEmergencia: true,
        var_acaoFormEmergencia: "Editar emergência",
        var_dadosEmergencia: ThisItem
    }
);
EditForm(FormCadastrarEmergencia)

UpdateContext(
    {
        var_visibleGerenciarEmergencia: true,
        var_cadastrarEmergencia: "PLEM",
        var_AeroSelectCadEmergencia: ComboboxCanvasAeroSelectCadEmergencia.Selected.Value,
        var_visibleEscolhaEmergencia: false
    }
);
Switch(
    varPerfilUser,
    "Base",
    ClearCollect(
        col_emergencias,
        Sort(
            Filter(
                tbl_Emergencias,
                Aeroporto = varAeroUser And Acionamento = "PLEM"
            ),
            Titulo,
            SortOrder.Ascending
        )
    ),
    ClearCollect(
        col_emergencias,
        Sort(
            Filter(
                tbl_Emergencias,
                Aeroporto = var_AeroSelectCadEmergencia And Acionamento = "PLEM"
            ),
            Titulo,
            SortOrder.Ascending
        )
    )
)

UpdateContext(
    {
        var_visibleGerenciarEmergencia: true,
        var_cadastrarEmergencia: "PRAI",
        var_AeroSelectCadEmergencia: ComboboxCanvasAeroSelectCadEmergencia.Selected.Value,
        var_visibleEscolhaEmergencia: false
    }
);
Switch(
    varPerfilUser,
    "Base",
    ClearCollect(
        col_emergencias,
        Sort(
            Filter(
                tbl_Emergencias,
                Aeroporto = varAeroUser And Acionamento = "PRAI"
            ),
            Titulo,
            SortOrder.Ascending
        )
    ),
    ClearCollect(
        col_emergencias,
        Sort(
            Filter(
                tbl_Emergencias,
                Aeroporto = var_AeroSelectCadEmergencia And Acionamento = "PRAI"
            ),
            Titulo,
            SortOrder.Ascending
        )
    )
)

Patch(
    col_emergencias,
    Coalesce(
        var_dadosEmergencia,
        Defaults(col_emergencias)
    ),
    Self.LastSubmit
);
UpdateContext({var_visibleFormEmergencia: false})

UpdateContext({var_visibleExcluirEmergencia: false});
RemoveIf(
    tbl_FluxogramaAcionamentos,
    Aeroporto = var_dadosEmergencia.Aeroporto And ID_emergencia = var_dadosEmergencia.ID
);
RemoveIf(
    col_emergencias,
    ID = var_dadosEmergencia.ID
);
RemoveIf(
    tbl_Emergencias,
    ID = var_dadosEmergencia.ID
);
Notify(
    "Emergência excluido com sucesso!",
    NotificationType.Warning
)
